-- Omnia Global Academy — Étape 3 — Internationalisation complète
-- Migration additive : langue préférée, registre des chaînes UI, cache et gouvernance.

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

ALTER TABLE public.user_profiles
  ADD COLUMN IF NOT EXISTS preferred_language text NOT NULL DEFAULT 'fr';

ALTER TABLE public.user_profiles
  DROP CONSTRAINT IF EXISTS user_profiles_preferred_language_check;
ALTER TABLE public.user_profiles
  ADD CONSTRAINT user_profiles_preferred_language_check
  CHECK (preferred_language IN ('fr','en','es','pt','ar','zh','ru','de'));

CREATE TABLE IF NOT EXISTS public.platform_ui_translations (
  source_hash text PRIMARY KEY,
  source_text text NOT NULL UNIQUE,
  translations jsonb NOT NULL DEFAULT '{}'::jsonb,
  reviewed_languages text[] NOT NULL DEFAULT ARRAY[]::text[],
  machine_generated_languages text[] NOT NULL DEFAULT ARRAY[]::text[],
  hit_count bigint NOT NULL DEFAULT 0,
  last_requested_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT platform_ui_source_length CHECK (char_length(source_text) BETWEEN 2 AND 500)
);

CREATE INDEX IF NOT EXISTS platform_ui_translations_source_trgm_idx
  ON public.platform_ui_translations USING gin (source_text gin_trgm_ops);
CREATE INDEX IF NOT EXISTS platform_ui_translations_updated_idx
  ON public.platform_ui_translations (updated_at DESC);

CREATE TABLE IF NOT EXISTS public.platform_ui_translation_rate_limits (
  quota_key text PRIMARY KEY,
  window_started_at timestamptz NOT NULL DEFAULT now(),
  request_count integer NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.platform_ui_translations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.platform_ui_translation_rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.platform_ui_translations FROM anon, authenticated;
REVOKE ALL ON public.platform_ui_translation_rate_limits FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.oga_i18n_register_sources(p_sources text[])
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_count integer := 0;
BEGIN
  INSERT INTO public.platform_ui_translations(source_hash,source_text)
  SELECT md5(trim(source)), trim(source)
  FROM unnest(coalesce(p_sources, ARRAY[]::text[])) source
  WHERE char_length(trim(source)) BETWEEN 2 AND 500
  ON CONFLICT (source_hash) DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;
REVOKE ALL ON FUNCTION public.oga_i18n_register_sources(text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oga_i18n_register_sources(text[]) TO service_role;

CREATE OR REPLACE FUNCTION public.oga_i18n_consume_quota(
  p_quota_key text,
  p_limit integer DEFAULT 60,
  p_window_seconds integer DEFAULT 3600
) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_now timestamptz := now();
  v_row public.platform_ui_translation_rate_limits%ROWTYPE;
BEGIN
  IF coalesce(trim(p_quota_key), '') = '' THEN RETURN false; END IF;
  INSERT INTO public.platform_ui_translation_rate_limits(quota_key, window_started_at, request_count, updated_at)
  VALUES (p_quota_key, v_now, 1, v_now)
  ON CONFLICT (quota_key) DO UPDATE SET
    window_started_at = CASE
      WHEN public.platform_ui_translation_rate_limits.window_started_at < v_now - make_interval(secs => greatest(60,p_window_seconds)) THEN v_now
      ELSE public.platform_ui_translation_rate_limits.window_started_at
    END,
    request_count = CASE
      WHEN public.platform_ui_translation_rate_limits.window_started_at < v_now - make_interval(secs => greatest(60,p_window_seconds)) THEN 1
      ELSE public.platform_ui_translation_rate_limits.request_count + 1
    END,
    updated_at = v_now
  RETURNING * INTO v_row;
  RETURN v_row.request_count <= greatest(1,p_limit);
END;
$$;
REVOKE ALL ON FUNCTION public.oga_i18n_consume_quota(text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oga_i18n_consume_quota(text,integer,integer) TO service_role;

CREATE OR REPLACE FUNCTION public.oga_i18n_overview()
RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path = public
AS $$
  WITH langs(code) AS (VALUES ('en'),('es'),('pt'),('ar'),('zh'),('ru'),('de')),
  totals AS (SELECT count(*)::integer AS total FROM public.platform_ui_translations),
  stats AS (
    SELECT l.code,
      count(*) FILTER (WHERE nullif(trim(t.translations ->> l.code),'') IS NOT NULL)::integer AS translated,
      count(*) FILTER (WHERE l.code = ANY(t.reviewed_languages))::integer AS reviewed
    FROM langs l CROSS JOIN public.platform_ui_translations t GROUP BY l.code
  )
  SELECT jsonb_build_object(
    'total', totals.total,
    'languages', coalesce(jsonb_object_agg(stats.code, jsonb_build_object(
      'translated', stats.translated,
      'reviewed', stats.reviewed,
      'percentage', CASE WHEN totals.total=0 THEN 100 ELSE round(stats.translated*100.0/totals.total,1) END
    )), '{}'::jsonb),
    'updated_at', (SELECT max(updated_at) FROM public.platform_ui_translations)
  ) FROM totals LEFT JOIN stats ON true GROUP BY totals.total;
$$;
REVOKE ALL ON FUNCTION public.oga_i18n_overview() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oga_i18n_overview() TO service_role;

CREATE OR REPLACE FUNCTION public.oga_i18n_list(
  p_language text,
  p_query text DEFAULT '',
  p_status text DEFAULT 'all',
  p_offset integer DEFAULT 0,
  p_limit integer DEFAULT 25
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_result jsonb;
BEGIN
  IF p_language NOT IN ('en','es','pt','ar','zh','ru','de') THEN RAISE EXCEPTION 'INVALID_LANGUAGE'; END IF;
  WITH filtered AS (
    SELECT t.* FROM public.platform_ui_translations t
    WHERE (coalesce(trim(p_query),'')='' OR t.source_text ILIKE '%'||trim(p_query)||'%' OR coalesce(t.translations->>p_language,'') ILIKE '%'||trim(p_query)||'%')
      AND (p_status='all'
        OR (p_status='missing' AND nullif(trim(t.translations->>p_language),'') IS NULL)
        OR (p_status='reviewed' AND p_language=ANY(t.reviewed_languages))
        OR (p_status='automatic' AND p_language=ANY(t.machine_generated_languages) AND NOT p_language=ANY(t.reviewed_languages)))
  ), page_rows AS (
    SELECT source_hash,source_text,translations->>p_language AS translation,
      p_language=ANY(reviewed_languages) AS reviewed,
      p_language=ANY(machine_generated_languages) AS machine_generated,
      hit_count,updated_at
    FROM filtered ORDER BY source_text OFFSET greatest(0,p_offset) LIMIT least(100,greatest(1,p_limit))
  )
  SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'rows',coalesce(jsonb_agg(to_jsonb(page_rows)),'[]'::jsonb)) INTO v_result FROM page_rows;
  RETURN v_result;
END;
$$;
REVOKE ALL ON FUNCTION public.oga_i18n_list(text,text,text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oga_i18n_list(text,text,text,integer,integer) TO service_role;

CREATE OR REPLACE FUNCTION public.oga_i18n_save(
  p_source_hash text,
  p_language text,
  p_translation text
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_row public.platform_ui_translations%ROWTYPE;
BEGIN
  IF p_language NOT IN ('en','es','pt','ar','zh','ru','de') THEN RAISE EXCEPTION 'INVALID_LANGUAGE'; END IF;
  IF coalesce(trim(p_translation),'')='' OR char_length(trim(p_translation))>1000 THEN RAISE EXCEPTION 'INVALID_TRANSLATION'; END IF;
  UPDATE public.platform_ui_translations SET
    translations = jsonb_set(translations, ARRAY[p_language], to_jsonb(trim(p_translation)), true),
    reviewed_languages = array(SELECT DISTINCT x FROM unnest(reviewed_languages || ARRAY[p_language]) x),
    machine_generated_languages = array_remove(machine_generated_languages,p_language),
    updated_at=now()
  WHERE source_hash=p_source_hash RETURNING * INTO v_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'SOURCE_NOT_FOUND'; END IF;
  RETURN jsonb_build_object('source_hash',v_row.source_hash,'source_text',v_row.source_text,'translation',v_row.translations->>p_language,'reviewed',true,'machine_generated',false,'hit_count',v_row.hit_count,'updated_at',v_row.updated_at);
END;
$$;
REVOKE ALL ON FUNCTION public.oga_i18n_save(text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oga_i18n_save(text,text,text) TO service_role;

